{
  "title": "Đà Lạt thong thả, cà phê ngắm phố",
  "summary": "Một ngày chậm rãi ở Đà Lạt, bớt đi bộ, thêm thời gian ngồi cà phê ngắm cảnh và ăn uống đúng điệu.",
  "stops": [
    {
      "poi_id": "p129",
      "kind": "activity",
      "must_do_id": "p129",
      "note": "Thung Lũng Tình Yêu vẫn là điểm hẹn sáng nay, đi xe tới nơi rồi thong thả dạo, không cần cuốc bộ xa."
    },
    {
      "poi_id": "p191",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa đúng chất Đà Lạt, bánh căn nóng hổi ăn xong còn kịp nghỉ trưa cho đã."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chiều ngồi cà phê view đẹp theo đúng gu, khỏi đi bộ nhiều mà vẫn thấy phố núi."
    },
    {
      "poi_id": "p165",
      "kind": "activity",
      "must_do_id": "p165",
      "note": "Chợ Đà Lạt ghé muộn một chút, vừa mát vừa ít chen chúc, ngắm nghía rồi ăn tối luôn cũng tiện."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ngồi quán quen ăn bữa đàng hoàng, khỏi phải đi xa, ngon quá (so tasty) là vừa."
    }
  ]
}
```

